import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { URL } from 'node:url';
import { CLASS_DEFINITIONS } from '../packages/card-definitions/dist/classes.js';

const schema = JSON.parse(
  readFileSync(
    new URL('../packages/card-definitions/content.schema.json', import.meta.url),
    'utf8',
  ),
);
const output =
  '# Generated by npm run sync:content-schema. Edit packages/card-definitions/content.schema.json.\n' +
  'extends RefCounted\n\n' +
  `const SCHEMA = ${JSON.stringify(schema, null, '\t')}\n\n` +
  `const CLASSES = ${JSON.stringify(Object.keys(CLASS_DEFINITIONS).sort())}\n`;
mkdirSync(new URL('../apps/godot-client/src/', import.meta.url), { recursive: true });
writeFileSync(new URL('../apps/godot-client/src/content_schema.gd', import.meta.url), output);
